class Solution {
    public int xorOperation(int n, int start) {
        int answer = 0;
        for (int i = 0; i < n; i++) {
            answer ^= start + 2 * i;
        }
        return answer;
    }
}

class Solution {
    public int xorOperation(int n, int start) {
        int answer = 0;
        int current = start;
        int remaining = n;
        while (remaining > 0) {
            answer ^= current;
            current += 2;
            remaining--;
        }
        return answer;
    }
}

class Solution {
    public int xorOperation(int n, int start) {
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = start + 2 * i;
        }

        int answer = 0;
        for (int value : nums) {
            answer ^= value;
        }
        return answer;
    }
}

class Solution {
    public int xorOperation(int n, int start) {
        int base = start >> 1;
        int highBits = xorPrefix(base - 1) ^ xorPrefix(base + n - 1);
        int lowBit = (n % 2) * (start & 1);
        return (highBits << 1) | lowBit;
    }

    private int xorPrefix(int x) {
        if (x < 0) {
            return 0;
        }
        int pattern = x & 3;
        if (pattern == 0) {
            return x;
        }
        if (pattern == 1) {
            return 1;
        }
        if (pattern == 2) {
            return x + 1;
        }
        return 0;
    }
}
